mapper.select:
select b.id, b.cfg_id, b.agent_id, b.app_secret, b.app_name, b.oa_page_url, b.oa_page_url_mobile, b.yx as bind_state, b.remark, b.modedatacreater, r.lastname as creator_name, b.modedatacreatedate, b.modedatacreatetime, b.modedatamodifydatetime, c.corp_name as cfg_name, c.corp_id as cfg_corp_id, c.qy as cfg_sync_enable from ${appBindTable} b left join ${cfgTable} c on c.id = b.cfg_id left join hrmresource r on r.id = b.modedatacreater
and b.cfg_id = #{cfgId}
and b.cfg_id in #{cid}
and (b.app_name like #{keyword} or b.agent_id like #{keyword} or b.oa_page_url like #{keyword} or b.oa_page_url_mobile like #{keyword} or c.corp_name like #{keyword} or b.remark like #{keyword})
order by b.cfg_id, b.id

mapper.update:
update ${table}
set yx = #{yx},
    modedatamodifier = #{modifier},
    modedatamodifydatetime = #{modifyTime}
where id = #{id}
